 85→function replaceTracksInPlaylist(username, playlist, tracks, callback) {
 86→    var maxTracksPerPlaylistAdd = 100;
 87→    var url = 'https://api.spotify.com/v1/users/' + username +
 88→        '/playlists/' + playlist + '/tracks';
 89→    var start = 0;
 90→    var thisTracks = tracks.slice(start, start + maxTracksPerPlaylistAdd);
 91→    var uris = { 'uris': thisTracks };
 92→
 93→    // PUT replaces all tracks, POST appends
 94→    $.ajax(url, {
 95→        type: 'PUT',
 96→        data: JSON.stringify(uris),
 97→        dataType: 'json',
 98→        processData:false,
 99→        headers: {
100→            'Authorization': 'Bearer ' + g_access_token,
101→            'Content-Type': 'application/json'
102→        },
103→        success: function(r) {
104→            if (start + maxTracksPerPlaylistAdd >= tracks.length) {
105→                callback(true);
106→            } else {
107→                showStatus(Math.round(100 * start / tracks.length)  + "% saved");
108→                addTracksToPlaylist(username, playlist, tracks,
109→                    start + maxTracksPerPlaylistAdd, callback);
110→            }
111→        },
112→        error: function(r, status, err) {
113→            if (r.status >= 200 && r.status <= 299) {
114→                if (start + maxTracksPerPlaylistAdd >= tracks.length) {
115→                    callback(true);
116→                } else {
117→                    showStatus(Math.round(100 * start / tracks.length)  + "% saved");
118→                    addTracksToPlaylist(username, playlist, tracks,
119→                        start + maxTracksPerPlaylistAdd, callback);
120→                }
121→            } else {
122→                callback(null);
123→            }
124→        }
125→    });
126→}
