 40→var deltaNames = {
 41→    0: "Never",
 42→    60: "Once a minute",
 43→    3600: "Once an hour",
 44→    86400: "Once a day",
 45→    604800: "Once a week",
 46→    2592000: "Once a month",
 47→}
