 49→function getDeltaName(delta) {
 50→    delta = parseInt(delta);
 51→    if (delta in deltaNames) {
 52→        return deltaNames[delta];
 53→    } else {
 54→        return fmtTime(delta);
 55→    }
 56→}
 57→
 58→function isValidDelta(val) {
 59→    return val in deltaNames;
