 66→function fmtTime(secs) {
 67→    function pad(v) {
 68→        var vs = v.toString();
 69→        if (vs.length == 1) {
 70→            vs = '0' + vs;
 71→        }
 72→        return vs;
 73→    }
 74→
 75→    if (isNaN(secs)) {
 76→        return "00:00:00";
 77→    }
 78→
 79→    var s = Math.round(secs);
 80→    var d = Math.floor(s / (3600 * 24));
 81→    s -= d * 3600 * 24;
 82→    var h = Math.floor(s / 3600);
 83→    s -= h * 3600;
 84→    var m = Math.floor(s/60);
 85→    s -= m * 60
 86→
 87→    prefix = d > 0 ? d + "d " : "";
 88→    if (h == 0) {
 89→        return prefix + pad(m) + ":" + pad(s);
 90→    } else {
 91→        return prefix + pad(h) + ":" + pad(m) + ":" + pad(s);
 92→    }
 93→}
